<section class="card"><div class="card-heading"><div><p class="section-kicker">Fulfillment workspace</p><h2>Orders</h2><p class="card-subtitle">Manual payments stay pending until you verify receipt.</p></div><div class="button-row"><a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/store/orders/export">Export CSV</a><form method="get" action="<?= e_attr(rtrim($siteBasePath,'/')) ?>/index.php"><input type="hidden" name="p" value="/admin/store/orders"><label>Status<select name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['new','confirmed','preparing','ready','completed','cancelled'] as $s): ?><option value="<?= e_attr($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach; ?></select></label></form></div></div><?php if(!$orders): ?><div class="empty-state"><strong>No matching orders</strong><span>New customer orders will appear here.</span></div><?php else: ?><div class="table-scroll"><table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Payment</th><th>Total</th><th>Placed</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><strong><?= e($o['order_number']) ?></strong><br><small><?= e(ucfirst($o['fulfillment_method'])) ?></small></td><td><?= e($o['customer_name']) ?><br><small><?= e($o['customer_email']) ?></small></td><td><span class="badge neutral"><?= e(ucfirst($o['status'])) ?></span></td><td><span class="badge <?= $o['payment_status']==='paid'?'ok':'warn' ?>"><?= e(ucfirst($o['payment_status'])) ?></span><br><small><?= e(ucfirst($o['payment_method'])) ?></small></td><td><strong><?= e($o['currency']) ?> $<?= number_format((int)$o['total_minor']/100,2) ?></strong></td><td><?= e($o['placed_at']) ?></td><td><a class="btn small secondary" href="<?= e_attr($basePath) ?>/admin/store/orders/view&id=<?= (int)$o['id'] ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
